// The object catalog (generated by tools/gen_catalog.py) and fuzzy search over it.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
export const CATALOG_PATH = path.join(here, 'data', 'catalog.json');
export const catalog = JSON.parse(fs.readFileSync(CATALOG_PATH, 'utf8'));

const byId = new Map(catalog.entries.map((e) => [e.id, e]));
export const getEntry = (id) => byId.get(id);

