// characters ported from Super Mario Sunshine name themselves in the catalog
const SUNSHINE = {};
export function nameSunshine(entries) { for (const e of entries) if (e.name && (e.id.startsWith('sms:') || e.id.startsWith('vehicle:') || e.id.startsWith('kt:'))) SUNSHINE[e.id] = e.name; } // (and the vehicles, the katana objects)
nameSunshine(catalog.entries);

export function friendlyName(id) {
  if (!id) return 'object';
  if (FRIENDLY[id]) return FRIENDLY[id];
  if (SUNSHINE[id]) return SUNSHINE[id];
  const base = id.replace(/^prop:/, '').split(':')[0];
  return base.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
}

