function tokens(s) {
  return String(s).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter(Boolean);
}

export function search(query, { limit = 12, includeProps = true } = {}) {
  const q = String(query || '').toLowerCase().trim();
  let terms = tokens(q);
  for (const [alias, target] of Object.entries(ALIASES)) {
    if (q.includes(alias)) terms = terms.concat(tokens(target));
  }
  terms = [...new Set(terms.filter((t) => !['the', 'a', 'an', 'some', 'of'].includes(t)))];
  if (!terms.length) return [];
  const scored = [];
  for (const e of catalog.entries) {
    if (!includeProps && e.prop) continue;
    const hay = `${e.id} ${e.behavior} ${e.model} ${e.gfx || ''} ${friendlyName(e.id)}`.toLowerCase();
    const idTokens = tokens(e.id);
    let score = 0;
    for (const t of terms) {
      if (idTokens.includes(t)) score += 6;
      else if (hay.includes(t)) score += 3;
      else if (t.length > 3 && hay.includes(t.slice(0, -1))) score += 1;
    }
    if (!score) continue;
    if (e.id === q.replace(/\s+/g, '_')) score += 20;
    if (e.prop) score -= 2;
    if (/^(static_object|seesaw_platform|sliding_platform2|falling_bowser_platform)/.test(e.id)) score -= 2;
    score -= idTokens.length * 0.1; // prefer the plain entry over variants
    scored.push([score, e]);
  }
  scored.sort((a, b) => b[0] - a[0]);
  return scored.slice(0, limit).map(([, e]) => describe(e));
}

export function describe(e) {
  const out = {
    id: e.id,
    name: friendlyName(e.id),
    behavior: e.behavior,
    model: e.model,
    from: e.levels.slice(0, 3).map((l) => catalog.levels[l]?.name || l),
  };
  if (e.params.length > 1 || (e.params[0] && e.params[0] !== '0x00000000')) out.typical_bparams = e.params;
  if (NOTES[e.id]) out.note = NOTES[e.id];
  if (e.prop) out.note = 'Static decoration (no behavior, no collision).';
  return out;
}

export function levelByKey(key) {
  if (key == null) return null;
  const k = String(key).toLowerCase().trim();
  for (const [slug, info] of Object.entries(catalog.levels)) {
    if (slug === k || String(info.num) === k || info.name.toLowerCase() === k) return { slug, ...info };
  }
  const t = tokens(k);
  let best = null;
  let bestScore = 0;
  for (const [slug, info] of Object.entries(catalog.levels)) {
    const name = tokens(info.name);
    const s = t.filter((w) => name.includes(w) || slug === w).length;
    if (s > bestScore) { bestScore = s; best = { slug, ...info }; }
  }
  return best;
}

export function levelName(num) {
  for (const [slug, info] of Object.entries(catalog.levels)) if (info.num === num) return info.name;
  return `Level ${num}`;
}
